const TEXT = { 'zh-Hans': zhHans, 'zh-Hant': zhHant, en };

let current = detect(typeof navigator === 'undefined' ? [] : navigator.languages ?? [navigator.language]);

export const lang = () => current;

export function t(key, vars = {}) {
  const s = TEXT[current][key] ?? zhHans[key] ?? key;
  return s.replace(/\{(\w+)\}/g, (_, k) => (k in vars ? String(vars[k]) : `{${k}}`));
}

// apply puts the current language into every element marked with
//   data-t="key"        text
//   data-t-html="key"   markup (only these trusted strings, never user input)
//   data-t-ph / data-t-title / data-t-aria   placeholder, title, aria-label
export function apply(root = document) {
  document.documentElement.lang = t('html.lang');
  document.title = t('title');
  document.querySelector('meta[name="description"]')?.setAttribute('content', t('meta.desc'));
  for (const el of root.querySelectorAll('[data-t]')) el.textContent = t(el.dataset.t);
  for (const el of root.querySelectorAll('[data-t-html]')) el.innerHTML = t(el.dataset.tHtml);
  for (const el of root.querySelectorAll('[data-t-ph]')) el.placeholder = t(el.dataset.tPh);
  for (const el of root.querySelectorAll('[data-t-title]')) el.title = t(el.dataset.tTitle);
  for (const el of root.querySelectorAll('[data-t-aria]')) el.setAttribute('aria-label', t(el.dataset.tAria));
}

export function setLang(l) {
  if (TEXT[l]) current = l;
}
